        except EOFError:
            pass
    else:
        print("\n  Scripts directory is already in PATH!")

    print("\n" + "=" * 60)
    print("  You can now run 'kittyclaw' from any terminal!")
    print("  Or use: python kitty_mascot.py")
    print("=" * 60 + "\n")

if __name__ == "__main__":
    install()
